'use strict';
let commentCounts=new Map(),community={uid:null,items:[],notices:[],events:[],reports:[],reportsPhase:'idle',eventsPhase:'idle',phase:'idle',error:null,stops:[]},commentStop=null,communityBusy=false,modalVersion=0;
const jsArg=value=>esc(JSON.stringify(value));
const originalOpenModal=openModal;openModal=function(title,body){commentStop?.();commentStop=null;modalVersion++;$('#modal').classList.remove('photo-viewer');originalOpenModal(title,body);};
const newest=items=>[...items].sort((a,b)=>(b.createdAt?.seconds||0)-(a.createdAt?.seconds||0)||b.id.localeCompare(a.id));
function resetCommunity(){globalThis.resetPostPhotos?.();commentCounts.clear();community.stops.forEach(stop=>stop());commentStop?.();commentStop=null;community={uid:null,items:[],notices:[],events:[],reports:[],reportsPhase:'idle',eventsPhase:'idle',phase:'idle',error:null,stops:[]};communityBusy=false;modalVersion++;}
function closeModal(){commentStop?.();commentStop=null;modalVersion++;$('#modal').close();}
function isAdmin(){return isMember()&&currentUser.isAdmin===true;}
async function startCommunity(){
 if(!isMember()||community.uid===currentUser.uid)return;
 resetCommunity();const session=community,uid=currentUser.uid;session.uid=uid;searchTerm='';feedLimit=24;session.phase='loading';session.eventsPhase='loading';
 try{const api=await chagokAuth.getCommunity();if(session!==community||uid!==currentUser?.uid)return;
  if(isAdmin()){session.reportsPhase='loading';session.stops.push(api.watchReports(uid,items=>{if(session!==community)return;session.reports=items;session.reportsPhase='ready';if(page==='admin')renderAdmin();},()=>{if(session!==community)return;session.reportsPhase='error';if(page==='admin')renderAdmin();}));}
  session.stops.push(api.watch(uid,isAdmin(),items=>{if(session!==community)return;session.items=items;session.phase='ready';session.error=null;refreshCommunityView();},error=>{if(session!==community)return;session.items=[];session.phase='error';session.error=error.code;refreshCommunityView();}));
  session.stops.push(api.watchEvents(uid,isAdmin(),items=>{if(session!==community)return;session.events=items;session.eventsPhase='ready';if(page==='events')renderEvents();},()=>{if(session!==community)return;session.events=[];session.eventsPhase='error';if(page==='events')renderEvents();}));
  session.stops.push(api.watchNotices(uid,items=>{if(session!==community)return;session.notices=items;refreshNotices();if(page==='admin')renderAdmin();},()=>{if(session===community){session.notices=[];refreshNotices();}}));
 }catch(error){if(session!==community)return;session.phase='error';session.error=error.code;refreshCommunityView();}
}
function retryCommunity(){resetCommunity();startCommunity();refreshCommunityView();}
function refreshCommunityView(){if(!isMember())return;if(page==='feed')renderFeed();if(page==='talk')renderTalk();if(page==='admin')renderAdmin();if(page==='events')renderEvents();refreshNotices();}
function refreshNotices(){document.querySelector('#shared-notices')?.remove();if(isMember()&&page!=='admin'&&community.notices.length)$('#app').insertAdjacentHTML('afterbegin',`<div id="shared-notices" class="notice">${newest(community.notices).map(n=>`<div>공지 · ${esc(n.title)}</div>`).join('')}</div>`);}
// Navigation also refreshes shared announcements without rebuilding open forms.
const originalCalendar=renderCalendar;renderCalendar=function(){originalCalendar();refreshNotices();};
const originalGo=go;go=function(p){if(p==='admin'&&!isAdmin()){toast('관리자 계정으로만 이용할 수 있어요.');return;}globalThis.resetPostPhotos?.();originalGo(p);refreshNotices();};
function posts(){return isMember()?newest(community.items.filter(p=>!p.hidden&&!p.deleted)):[];}
function communityMessage(){return community.phase==='error'?`<div class="notice" role="alert">게시판을 불러오지 못했어요. ${community.error==='permission-denied'?'새 게시판 접근 규칙이 적용됐는지 운영자에게 확인해주세요.':esc(cloudError(community.error))} <button class="small-btn" onclick="retryCommunity()">다시 시도</button></div>`:community.phase!=='ready'?'<p class="empty" role="status">회원들의 이야기를 불러오고 있어요…</p>':'';}
function postDate(p){return p.createdAt?.seconds?new Date(p.createdAt.seconds*1000).toLocaleDateString('ko-KR'):'방금';}
function postActions(p,inDetail=false){const saved=state.saved.includes(p.id);return `<button aria-pressed="${saved}" onclick="${inDetail?`toggleSavedHere(this,${jsArg(p.id)})`:`toggle('saved',${jsArg(p.id)})`}">${saved?'저장됨':'저장'}</button>${p.authorUid!==currentUser.uid?`<button onclick="reportPost(${jsArg(p.id)})">신고</button>`:''}${p.authorUid===currentUser.uid?`<button onclick="editPost(${jsArg(p.id)})">수정</button><button class="danger" onclick="askDeletePost(${jsArg(p.id)})">삭제</button>`:''}`;}
function postCard(p){return `<article class="card"><div class="meta">${esc(p.author)} · ${postDate(p)}</div>${chip(p)}<h2><button class="card-title" onclick="openPost(${jsArg(p.id)})">${esc(p.name)}</button></h2>${p.photoCount?`<div class="post-photos" data-post-photos="${esc(p.id)}"><span class="sub">사진 ${p.photoCount}장 불러오는 중…</span></div>`:''}<p class="post-note clamp">${esc(p.note)}</p><div class="card-actions"><button onclick="openPost(${jsArg(p.id)})">댓글 <span data-comment-count="${esc(p.id)}"></span></button>${postActions(p)}</div></article>`;}
function renderFeed(){if(!requireMember())return;const items=posts().filter(p=>(p.kind==='record'||filter==='저장한 기록')&&(filter==='전체'||p.type===filter||filter==='저장한 기록'&&state.saved.includes(p.id)));$('#app').innerHTML=head('차생활 둘러보기','회원들의 찻자리에서 발견하는 새로운 취향.','<button class="primary" onclick="editPost(null,\'record\')">＋ 차생활 공유하기</button>')+`<div class="filters">${['전체','우롱차','보이차','홍차','저장한 기록'].map(t=>`<button class="${filter===t?'active':''}" onclick="filter='${t}';feedLimit=24;renderFeed()">${t}</button>`).join('')}</div>`+searchControls()+communityMessage()+`<div class="cards">${matchingPosts(items).slice(0,feedLimit).map(postCard).join('')|| (community.phase==='ready'?'<p class="empty">조건에 맞는 글이 없어요. 검색어나 차 종류를 바꿔보세요.</p>':'')}</div>${morePosts(items)}`;bindSearch();refreshNotices();globalThis.mountPostPhotos?.();mountCommentCounts();}
function renderTalk(){if(!requireMember())return;const items=posts().filter(p=>p.kind==='talk');$('#app').innerHTML=head('이야기방','보이차 · 우롱차 · 홍차에 관한 질문과 이야기를 나눠요.','<button class="primary" onclick="editPost(null,\'talk\')">＋ 이야기 쓰기</button>')+searchControls()+communityMessage()+`<div class="cards">${matchingPosts(items).slice(0,feedLimit).map(postCard).join('')||(community.phase==='ready'?'<p class="empty">조건에 맞는 이야기가 없어요. 첫 이야기를 남겨보세요.</p>':'')}</div>${morePosts(items)}`;bindSearch();refreshNotices();globalThis.mountPostPhotos?.();mountCommentCounts();}

async function editPost(id=null,kind='record',seed={}){
 const linked=state.records.find(r=>r.sharedPostId===id);if(id&&linked)return editRecord(linked.id);
 if(!requireMember())return;const p=id?community.items.find(p=>p.id===id):{...seed,kind};if(!p||p.deleted||(id&&p.authorUid!==currentUser.uid))return;
 let photos=[];
 if(id&&p.photoCount){closeModal();openModal('게시글 불러오기','<p role="status">첨부 사진을 불러오고 있어요…</p>');const loadVersion=modalVersion,uid=currentUser.uid;try{const api=await chagokAuth.getCommunity();photos=await api.loadPhotos(uid,id);if(loadVersion!==modalVersion||uid!==currentUser?.uid)return;}catch(error){if(loadVersion===modalVersion)openModal('사진을 불러오지 못했어요',`<p class="sub">사진을 보존하기 위해 수정을 열지 않았어요. 잠시 후 다시 시도해주세요.</p><button class="primary" onclick="editPost(${jsArg(id)})">다시 시도</button>`);return;}}
 closeModal();openModal(id?'게시글 수정':p.kind==='talk'?'이야기 쓰기':'차생활 공유하기',`<form id="post-form"><p class="notice">게시하면 로그인한 모든 회원이 볼 수 있어요. 개인 캘린더에도 남기려면 ‘차 기록하기’에서 공개를 선택해주세요.</p><label class="field">차 종류<select name="type">${['우롱차','보이차','홍차'].map(t=>`<option ${p.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">제목<input name="name" required maxlength="80" value="${esc(p.name||'')}" placeholder="나누고 싶은 이야기"></label><label class="field">내용<textarea name="note" required maxlength="3000" placeholder="향과 맛, 궁금한 점을 편하게 나눠요.">${esc(p.note||'')}</textarea></label><div id="post-photo-editor"></div><p class="sub">가향차와 대용차는 다루지 않아요.</p><p id="community-error" class="form-error" role="alert"></p><div class="form-actions"><button class="small-btn" type="button" onclick="closeModal()">취소</button><button class="primary" type="submit">${id?'수정 저장':'게시하기'}</button></div></form>`);
 const photoEditor=ChagokPhotos.editor($('#post-photo-editor'),photos,busy=>{const button=$('#post-form [type=submit]');if(button)button.disabled=busy;});
 const version=modalVersion;$('#post-form').onsubmit=async e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));if(!data.name.trim()||!data.note.trim())return toast('제목과 내용을 입력해주세요.');let attached;try{attached=photoEditor.get()}catch(error){$('#community-error').textContent=error.message;return;}const ok=await communityAction(api=>api.savePost(currentUser.uid,{...data,kind:p.kind,author:nickname(),photos:attached},id,p.revision),e.target);if(ok&&version===modalVersion){closeModal();go(p.kind==='talk'?'talk':'feed');toast('게시글을 올렸어요.');}};
}
async function communityAction(work,form){
 if(!requireMember()||communityBusy)return false;const session=community,uid=currentUser.uid;communityBusy=true;
 const button=form?.querySelector('[type=submit]');if(button)button.disabled=true;
 try{const api=await chagokAuth.getCommunity();if(session!==community||uid!==currentUser?.uid)return false;await work(api);return session===community&&uid===currentUser?.uid;}
 catch(error){if(session===community){const message=cloudError(error.code);toast(message);const inline=$('#community-error');if(inline)inline.textContent=message;}return false;}
 finally{if(session===community)communityBusy=false;if(button)button.disabled=false;}
}
function askDeletePost(id){const p=community.items.find(p=>p.id===id);if(!requireMember()||p?.authorUid!==currentUser.uid)return;closeModal();openModal('게시글을 삭제할까요?',`<p class="sub">게시글과 첨부 사진을 삭제하면 다른 회원에게 더 이상 보이지 않아요.</p><p id="community-error" role="alert"></p><div class="form-actions"><button class="small-btn" onclick="closeModal()">취소</button><button class="primary" onclick="deleteSharedPost(${jsArg(id)},${p.revision})">삭제하기</button></div>`);}
async function deleteSharedPost(id,revision){const version=modalVersion;if(await communityAction(api=>api.deletePost(currentUser.uid,id,revision))){if(version===modalVersion)closeModal();toast('게시글을 삭제했어요.');}}
function commentTime(c){return c.createdAt?.seconds?new Date(c.createdAt.seconds*1000).toLocaleString('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}):'방금';}
function showCommentCount(id,count){commentCounts.set(id,Promise.resolve(count));document.querySelectorAll('[data-comment-count]').forEach(el=>{if(el.dataset.commentCount===id)el.textContent=count;});const here=$('#detail-comment-count');if(here)here.textContent=count;}
function mountCommentCounts(){
 if(!isMember())return;const uid=currentUser.uid,session=community;
 document.querySelectorAll('[data-comment-count]').forEach(el=>{
  const id=el.dataset.commentCount;
  if(!commentCounts.has(id))commentCounts.set(id,chagokAuth.getCommunity().then(api=>api.countComments(uid,id)));
  commentCounts.get(id).then(count=>{if(session===community&&el.isConnected)el.textContent=count;},()=>{if(session===community)commentCounts.delete(id);});
 });
}
async function toggleSavedHere(button,id){button.disabled=true;await toggle('saved',id);if(!button.isConnected)return;const saved=state.saved.includes(id);button.textContent=saved?'저장됨':'저장';button.setAttribute('aria-pressed',saved);button.disabled=false;}
function openPost(id){
 if(!requireMember())return;const p=posts().find(p=>p.id===id);if(!p)return;closeModal();
 openModal(esc(p.name),`<div class="post-detail"><div class="meta">${esc(p.author)} · ${postDate(p)}</div>${chip(p)}${p.photoCount?'<div class="post-photos" id="detail-photos"><span class="sub">사진을 불러오고 있어요…</span></div>':''}<p class="post-note">${esc(p.note)}</p><div class="card-actions">${postActions(p,true)}</div></div><section class="detail-comments"><h3>댓글 <span id="detail-comment-count"></span></h3><div id="shared-comments" aria-live="polite">댓글을 불러오고 있어요…</div><form id="shared-comment-form"><label class="field"><span class="sr-only">댓글</span><textarea name="text" required maxlength="500" placeholder="함께 나누고 싶은 이야기"></textarea></label><p id="community-error" class="form-error" role="alert"></p><button class="primary" type="submit">댓글 남기기</button></form></section>`);
 const version=modalVersion,uid=currentUser.uid;
 chagokAuth.getCommunity().then(api=>{
  if(version!==modalVersion||uid!==currentUser?.uid)return;
  if(p.photoCount)(photoCache.has(id)?Promise.resolve(photoCache.get(id)):api.loadPhotos(uid,id)).then(photos=>{if(version!==modalVersion)return;photoCache.set(id,photos);$('#detail-photos').innerHTML=photos.map((src,i)=>`<button class="photo-thumb" onclick="openPostPhoto(${jsArg(id)},${i})" aria-label="사진 ${i+1} 크게 보기"><img src="${src}" alt="게시글 사진 ${i+1}" decoding="async"></button>`).join('');},()=>{if(version===modalVersion)$('#detail-photos').textContent='사진을 불러오지 못했어요.';});
  commentStop=api.watchComments(uid,id,items=>{if(version!==modalVersion)return;showCommentCount(id,items.length);$('#shared-comments').innerHTML=newest(items).reverse().map(c=>`<div class="comment"><div class="comment-meta"><b>${esc(c.author)}</b><span>${commentTime(c)}</span></div><p class="post-note">${esc(c.text)}</p>${c.authorUid===uid||isAdmin()?`<button class="text-button" onclick="deleteSharedComment(${jsArg(id)},${jsArg(c.id)})">댓글 삭제</button>`:''}</div>`).join('')||'<p class="empty">첫 댓글을 남겨보세요.</p>';},error=>{if(version!==modalVersion)return;$('#shared-comments').textContent='댓글을 불러올 수 없어요. 게시글이 숨겨졌거나 삭제되었을 수 있어요.';$('#shared-comment-form').hidden=true;});
 }).catch(error=>{if(version===modalVersion)$('#shared-comments').textContent=cloudError(error.code)});
 $('#shared-comment-form').onsubmit=async e=>{e.preventDefault();const text=new FormData(e.target).get('text').trim();if(!text)return;const form=e.target;if(await communityAction(api=>api.comment(uid,id,text,nickname()),form)){if(version===modalVersion)form.reset();}};
}
async function deleteSharedComment(id,commentId){await communityAction(api=>api.deleteComment(currentUser.uid,id,commentId));}
function renderAdmin(){if(!requireMember())return;if(!isAdmin()){$('#app').innerHTML=head('관리자','관리자 계정만 이용할 수 있어요.');return;}const noticeDraft=document.querySelector('#notice-form input')?.value||'';$('#app').innerHTML=head('커뮤니티 관리','공지를 전하고 게시글 공개 상태를 관리해요.','<button class="primary" onclick="go(\'events\')">이벤트 설정</button>')+communityMessage()+`<h2>공지 관리</h2><form id="notice-form" class="list-item"><label class="field">공지 내용<input name="title" required maxlength="100" placeholder="회원에게 알릴 소식"></label><button class="primary" type="submit">공지 등록</button></form>${newest(community.notices).map(n=>`<div class="list-item"><p>${esc(n.title)}</p><button class="danger" onclick="removeAnnouncement(${jsArg(n.id)})">공지 삭제</button></div>`).join('')}<h2 class="section-title">게시글 관리</h2>${newest(community.items).filter(p=>!p.deleted).map(p=>`<div class="list-item"><div><h3>${esc(p.name)}</h3><p>${esc(p.author)} · ${p.kind==='talk'?'이야기방':'차생활'} · ${p.hidden?'숨김':'공개'}</p><p class="post-note">${esc(p.note)}</p></div><div class="report-actions"><button class="small-btn" onclick="moderate(${jsArg(p.id)})">${p.hidden?'다시 공개':'글 숨기기'}</button>${p.authorUid!==currentUser.uid&&!(community.bans||[]).some(b=>b.id===p.authorUid)?`<button class="small-btn" onclick="banMember(${jsArg(p.authorUid)})">작성자 이용 제한</button>`:''}</div></div>`).join('')||'<p class="empty">관리할 게시글이 없어요.</p>'}`;
 if(noticeDraft)$('#notice-form input').value=noticeDraft;
 $('#notice-form').onsubmit=async e=>{e.preventDefault();const text=new FormData(e.target).get('title').trim();if(!text)return;const form=e.target;if(await communityAction(api=>api.notice(currentUser.uid,text),form)){document.querySelector('#notice-form')?.reset();toast('공지를 등록했어요.');}};
}
async function moderate(id){if(!isAdmin())return;const p=community.items.find(p=>p.id===id);if(p&&await communityAction(api=>api.moderate(currentUser.uid,id,!p.hidden,p.revision)))toast(p.hidden?'다시 공개했어요.':'게시글을 숨겼어요.');}
async function removeAnnouncement(id){if(isAdmin())await communityAction(api=>api.deleteNotice(currentUser.uid,id));}
async function toggle(key,id){if(!requireMember()||key!=='saved')return;const next=draftState();next.saved=next.saved.includes(id)?next.saved.filter(x=>x!==id):[...next.saved,id];if(await commitState(next))refreshCommunityView();}
$('#modal').addEventListener('cancel',()=>{commentStop?.();commentStop=null;modalVersion++;});
if(isMember())startCommunity();
